a['about']=a['about'].replace('In a parallel Athens,','Elsewhere in Athens,').replace('In the wood that surrounds both,','In the nearby wood,').replace('Puck applies it to the wrong men,','Puck puts it on Lysander instead of Demetrius,').replace("parodies Romeo and Juliet's plot inside its own comic frame.","gives a pair of doomed lovers a comic frame.").replace('Four lovers redirect their affections under the influence of a flower;','Two young men change their affections under the influence of a flower while the women they court try to make sense of it;')
a['whyItMatters'][0]['body']=a['whyItMatters'][0]['body'].replace('Each of the four young Athenians spends a night in the wood being made to love the wrong person by the juice of a flower.','Four young Athenians spend the night in the wood. Only Lysander and Demetrius receive the flower’s juice. Both wake up convinced that Helena alone deserves their love.')
a['whyItMatters'][2]['body']=a['whyItMatters'][2]['body'].split(' Shakespeare establishes')[0]+' In the wood, the city’s rules briefly lose their force. When the lovers return, Theseus overrules Egeus and three marriages replace the threatened execution.'
a['cast'][2]['description']=a['cast'][2]['description'].replace('Her opening speech about how the lovers\' quarrel','Her speech about how her quarrel with Oberon')
